import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with targeted ELA properties.
    """
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 4:
        raise ValueError("Input must be a 1D array of shape (4,).")

    # Skewed quadratic with interaction
    q = x[0]**2 + 0.5*x[0]*x[1] - 0.3*x[2]*x[3] +  1.1*x[1]**2 + 0.7*x[2]**2 - 0.2 *x[3]**2
    f2 = 0.2 * (q**3 + 0.3 * q)

    # Product of sines for interactions
    f3 = np.prod(np.sin(x * np.array([1.2, 1.5, 0.8, 1.05])))

    # Chebyshev polynomial harmonic distortion
    def chebyshev_polynomial(x, n):
        if n == 0:
            return 1
        elif n == 1:
            return x
        else:
            return 2 * x * chebyshev_polynomial(x, n-1) - chebyshev_polynomial(x, n-2)

    cheb = np.sum([chebyshev_polynomial(xi, i+1) for i, xi in enumerate(x)])
    f4 = 0.05*cheb

    # Combining components
    f = 0.7 * f2 + 0.6 * f3 + f4
    return float(f)
